// ESLint having trouble with tanstack/react-table named imports
// eslint-disable-next-line import/named, prettier/prettier
import { getCoreRowModel, getExpandedRowModel, getFilteredRowModel, getPaginationRowModel, getSortedRowModel, getGroupedRowModel } from "@tanstack/react-table";
import {
  type TableOptions,
  type Row,
  type Table as TanstackTable,
  useReactTable,
  type TableState,
  type OnChangeFn,
  type SortingState,
  type PaginationState,
  type ColumnFiltersState,
  type RowSelectionState,
  type ExpandedState,
} from "@tanstack/react-table";
import React, { forwardRef, useState, useMemo, useEffect } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Checkbox } from "@components/checkbox";
import { Cell } from "@components/cell";

import { type ListProps } from "./list.types";
import { getListChildren } from "./utils/get-list-children";
import {
  ListHeader,
  ListBody,
  ListToolbar,
  ListFooter,
  ListSearch,
  ListFilterIconButton,
  ListFilterIconButtonBadge,
  ListPagination,
  ListPageSizeSelect,
  ListFilterChipBar,
  ListEmptyState,
  ListToolbarTrailing,
} from "./subcomponents";
import { ListContext, ListStateContext } from "./hooks/use-list";
import { useListKeyboardNav } from "./hooks/use-list-keyboard-nav";
import { ListKeyboardNavContext } from "./hooks/use-list-keyboard-nav-context";
import { StyledList, ListClasses } from "./list.styles";

const ListRoot = forwardRef(
  <TData extends object>(
    {
      styleSlots,
      variant = "default",
      data,
      columns,
      children,
      className,
      enableRowSelection = false,
      enableRowExpansion = false,
      enableKeyboardShortcuts = true,
      initialState = {
        sorting: [],
        pagination: { pageIndex: 0, pageSize: 10 },
        rowSelection: {},
        columnFilters: [],
        globalFilter: "",
      },
      state: controlledState,
      onGlobalFilterChange: onGlobalFilterChange,
      onSortingChange: onSortingChange,
      onPaginationChange: onPaginationChange,
      onColumnFiltersChange: onColumnFiltersChange,
      onExpandedChange: onExpandedChange,
      onRowSelectionChange: onRowSelectionChange,
      pageCount: controlledPageCount,
      rowSelectionAriaLabels = {
        selectAll: "Select all rows",
        selectRow: "Select row",
      },
      expandRowAriaLabels = {
        expand: "Expand row",
        collapse: "Collapse row",
      },
      expandRowIcons,
      ...props
    }: ListProps<TData>,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const [listHeight, setListHeight] = useState(0);
    const listContainerRef = React.useRef<HTMLDivElement>(null);

    const [globalFilter, setGlobalFilter] = useState(initialState?.globalFilter ?? "");
    const [sorting, setSorting] = useState<SortingState>(initialState?.sorting ?? []);
    const [pagination, setPagination] = useState<PaginationState>({
      pageIndex: initialState?.pagination?.pageIndex ?? 0,
      pageSize: initialState?.pagination?.pageSize ?? 10,
    });
    const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(
      initialState?.columnFilters ?? [],
    );
    const [rowSelection, setRowSelection] = useState<RowSelectionState>(
      initialState?.rowSelection ?? {},
    );
    const [expanded, setExpanded] = useState<ExpandedState>(initialState?.expanded ?? {});

    const state: Partial<TableState> = useMemo(
      () => ({
        ...controlledState,
        globalFilter: controlledState?.globalFilter ?? globalFilter,
        sorting: controlledState?.sorting ?? sorting,
        pagination: controlledState?.pagination ?? pagination,
        columnFilters: controlledState?.columnFilters ?? columnFilters,
        rowSelection: controlledState?.rowSelection ?? rowSelection,
        expanded: controlledState?.expanded ?? expanded,
      }),
      [controlledState, globalFilter, sorting, pagination, columnFilters, rowSelection, expanded],
    );

    const handleGlobalFilterChange: OnChangeFn<string> = (updater) => {
      onGlobalFilterChange?.(updater);
      if (!controlledState?.globalFilter) {
        setGlobalFilter(updater);
      }
    };

    const handleSortingChange: OnChangeFn<SortingState> = (updater) => {
      onSortingChange?.(updater);
      if (!controlledState?.sorting) {
        setSorting(updater);
      }
    };

    const handlePaginationChange: OnChangeFn<PaginationState> = (updater) => {
      onPaginationChange?.(updater);
      if (!controlledState?.pagination) {
        setPagination(updater);
      }
    };

    const handleColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) => {
      onColumnFiltersChange?.(updater);
      if (!controlledState?.columnFilters) {
        setColumnFilters(updater);
      }
    };

    const handleRowSelectionChange: OnChangeFn<RowSelectionState> = (updater) => {
      onRowSelectionChange?.(updater);
      if (!controlledState?.rowSelection) {
        setRowSelection(updater);
      }
    };

    const handleExpandedChange: OnChangeFn<ExpandedState> = (updater) => {
      onExpandedChange?.(updater);
      if (!controlledState?.expanded) {
        setExpanded(updater);
      }
    };

    const list = useReactTable({
      data,
      columns: [
        ...(enableRowSelection
          ? [
              {
                id: "select",
                header: ({ table }: { table: TanstackTable<TData> }) => (
                  <Checkbox
                    aria-label={rowSelectionAriaLabels.selectAll}
                    checked={
                      table.getIsAllRowsSelected()
                        ? true
                        : table.getIsSomeRowsSelected()
                          ? "indeterminate"
                          : false
                    }
                    onCheckedChange={(value) => table.toggleAllRowsSelected(!!value)}
                  />
                ),
                cell: ({ row }: { row: Row<TData> }) => (
                  <Checkbox
                    aria-label={rowSelectionAriaLabels.selectRow}
                    checked={row.getIsSelected()}
                    onCheckedChange={(value) => row.toggleSelected(!!value)}
                  />
                ),
                enableSorting: false,
                enableColumnFilter: false,
                size: 40,
                minSize: 40,
                maxSize: 40,
              },
            ]
          : []),
        ...(enableRowExpansion
          ? [
              {
                id: "expand",
                header: () => null,
                cell: ({ row }: { row: Row<TData> }) => (
                  <Cell.ExpandToggle
                    canExpand={row.getCanExpand()}
                    collapseAriaLabel={expandRowAriaLabels.collapse}
                    collapsedIcon={expandRowIcons?.collapsed}
                    expandAriaLabel={expandRowAriaLabels.expand}
                    expandedIcon={expandRowIcons?.expanded}
                    isExpanded={row.getIsExpanded()}
                    onToggle={row.getToggleExpandedHandler()}
                  />
                ),
                enableSorting: false,
                enableColumnFilter: false,
                size: 24,
                minSize: 24,
                maxSize: 24,
              },
            ]
          : []),
        ...columns,
      ],
      state,
      pageCount: controlledPageCount,
      enableRowSelection,
      onGlobalFilterChange: handleGlobalFilterChange,
      onSortingChange: handleSortingChange,
      onPaginationChange: handlePaginationChange,
      onColumnFiltersChange: handleColumnFiltersChange,
      onRowSelectionChange: handleRowSelectionChange,
      onExpandedChange: handleExpandedChange,
      getCoreRowModel: getCoreRowModel(),
      getExpandedRowModel: getExpandedRowModel(),
      getFilteredRowModel: getFilteredRowModel(),
      getPaginationRowModel: getPaginationRowModel(),
      getSortedRowModel: getSortedRowModel(),
      getGroupedRowModel: getGroupedRowModel(),
      ...props,
    } as TableOptions<TData>);

    const { listRef, handleKeyDown } = useListKeyboardNav();

    const { toolbar, header, body, footer, filterChipBars, emptyState } = getListChildren(children);

    useEffect(() => {
      if (listContainerRef.current) {
        setListHeight(listContainerRef.current.offsetHeight);
      }
    }, [listContainerRef]);
    const { rows } = list.getRowModel();
    const pageSize = state.pagination?.pageSize ?? 10;
    const emptyRows = rows.length < pageSize ? pageSize - rows.length : 0;

    return (
      <ListContext.Provider value={list}>
        <ListStateContext.Provider value={list.getState()}>
          <ListKeyboardNavContext.Provider value={{ enableKeyboardShortcuts, handleKeyDown }}>
            <StyledList
              ref={ref}
              className={clsx(ListClasses.root, className)}
              currentTheme={theme}
              styleSlots={styleSlots}
              variant={variant}
            >
              {toolbar}
              {filterChipBars}
              <div className={ListClasses.listContainer}>
                {emptyRows !== pageSize || !emptyState ? (
                  <div ref={listContainerRef}>
                    <table ref={listRef} className={ListClasses.list}>
                      {header}
                      {body}
                    </table>
                    {footer}
                  </div>
                ) : (
                  <div ref={listContainerRef} style={{ display: "flex", height: listHeight }}>
                    {emptyState}
                  </div>
                )}
              </div>
            </StyledList>
          </ListKeyboardNavContext.Provider>
        </ListStateContext.Provider>
      </ListContext.Provider>
    );
  },
);

ListRoot.displayName = "List";

const List = Object.assign(ListRoot, {
  // ofType provides a typed view of the generic List component for a specific row type TData.
  // Usage: const FileList = List.ofType<File>(); then <FileList data={...} columns={...} />
  ofType: <TData extends object>() => ListRoot as unknown as React.ComponentType<ListProps<TData>>,
  Toolbar: ListToolbar,
  ToolbarTrailing: ListToolbarTrailing,
  Header: ListHeader,
  Body: ListBody,
  Footer: ListFooter,
  Search: ListSearch,
  FilterIconButton: ListFilterIconButton,
  FilterIconButtonBadge: ListFilterIconButtonBadge,
  FilterChipBars: ListFilterChipBar,
  Pagination: ListPagination,
  PageSizeSelect: ListPageSizeSelect,
  EmptyState: ListEmptyState,
});
export default List;
